import json
from pathlib import Path
D=json.loads(Path('docs/benchmarks/data/delivery3-diagnosis-v1.json').read_text())
for r in D['phases']:
 if r['family']=='dense-generic-512' and r['tier']=='certified-1e-9':
  print('PHASE',json.dumps(r))
for r in D['dense_target_forecasts']:print('TARGET',r)
for r in D['native_gpu_cost_bounds']:
 if r['tier']=='certified-1e-9' and r['lifecycle']=='prepared':print('FAMILY',r['family'],{k:v['median'] for k,v in r['summary'].items()})
for r in D['prepared_positions']:
 if r['family']=='dense-generic-512' and r['tier']=='certified-1e-9':print('POSITION',json.dumps(r))
for r in D['instrumented_profile']:
 if r['family']=='dense-generic-512' and r['tier']=='certified-1e-9' and r['variant'] in ('control','batch','overlap'):
  print('PROFILE',r['lifecycle'],r['lane'],r['variant'],{k:{n:round(v['mean'],6) for n,v in r[k].items()} for k in ('parent','child','setup','delivery') if r[k]})
for d in D['primary_decisions']:
 for g in d['guards']:
  if g['decision']!='supported':
   r=next(r for r in D['pairs'] if all(r[k]==d[k] for k in ('lifecycle','lane','tier')) and r['family']==g['family'])
   print('GUARD',r['lifecycle'],r['lane'],r['tier'],r['family'],'positive',r['positive_guard_blocks'],'order',{k:round(v['ratio']['median'],5) for k,v in r['by_order'].items()},'halves',r['first_half_ratio'],r['last_half_ratio'],'corr',r['log_ratio_associations'])
for r in D['pairs']:
 if r['family']=='dense-generic-512' and r['tier']=='certified-1e-9':print('PAIR',json.dumps(r))

